mapper.select:
SELECT s.id AS id, h.title AS title, h.created_at AS start_date, CASE WHEN DATEDIFF(h.start_date, CURDATE()) > 0 THEN CONCAT('D-', DATEDIFF(h.start_date, CURDATE())) WHEN DATEDIFF(h.start_date, CURDATE()) = 0 THEN 'D-Day' ELSE CONCAT('D+', ABS(DATEDIFF(h.start_date, CURDATE()))) END AS d_day, CASE WHEN s.id IS NOT NULL THEN '제출' ELSE '미제출' END AS submission_status, NULL AS is_invalidated, IFNULL(e.is_pass, 0) AS score, 'homework' AS content_type FROM homework h LEFT JOIN homework_submission s ON h.id = s.homework_id AND s.learner_id = #{userId} LEFT JOIN homework_eval e ON e.hs_id = s.id WHERE h.course_id = #{courseId}
UNION ALL
SELECT t.id AS id, t.title AS title, t.created_at AS start_date, CASE WHEN DATEDIFF(t.start_date, CURDATE()) > 0 THEN CONCAT('D-', DATEDIFF(t.start_date, CURDATE())) WHEN DATEDIFF(t.start_date, CURDATE()) = 0 THEN 'D-Day' ELSE CONCAT('D+', ABS(DATEDIFF(t.start_date, CURDATE()))) END AS d_day, s.submission_status AS submission_status, s.is_invalidated AS is_invalidated, s.score AS score, 'test' AS content_type FROM test t JOIN test_submission s ON t.id = s.test_id WHERE s.learner_id = #{userId} and t.course_id = #{courseId}
ORDER BY start_date ASC
